/**
 * @file config.h
 * @brief Configuration header for Smol Slime (nRF52840 + LSM6DSV) 1000 Hz Gyro Firmware
 * 
 * Instructions:
 * 1. Flash and run `imu_finder.uf2` first.
 * 2. Open USB Serial Monitor (115200 baud).
 * 3. Copy the output block generated by `imu_finder` and paste it below into the IMU PINOUT section.
 */

#ifndef CONFIG_H_
#define CONFIG_H_

#include <stdint.h>
#include <stdbool.h>
#include <Arduino.h>

// ==============================================================================
// 1. HARDWARE POWER SWITCH (CRITICAL: DO NOT CHANGE)
// ==============================================================================
// On the SuperMini nRF52840 / Smol Slime board, P0.13 controls the external VCC cutoff.
// Driving P0.13 LOW turns OFF power to the 3.3V/VCC pin.
// Driving P0.13 HIGH enables power to the IMU module.
// NEVER use P0.13 as a bus signal pin!
#define PIN_POWER_VCC_CUTOFF      13  // P0.13 (NRF_GPIO_PIN_MAP(0, 13))
#define POWER_ON_DELAY_MS         50  // Wait 50 ms after power-on for IMU power rail to stabilize

// ==============================================================================
// 2. BUS SELECTION (Choose IMU_BUS_SPI or IMU_BUS_I2C)
// ==============================================================================
#define IMU_BUS_SPI               1
#define IMU_BUS_I2C               2

// Set the active bus protocol here (copy from imu_finder output):
#define IMU_BUS                   IMU_BUS_SPI

// ==============================================================================
// 3. IMU PIN ASSIGNMENTS (PLACEHOLDERS: FILL FROM IMU_FINDER OUTPUT)
// ==============================================================================
// Candidate pins wired to LSM6DSV on Smol Slime:
//   P0.17 (D2), P0.20 (D3), P0.22 (D4), P0.24 (D5),
//   P1.00 (D6), P0.11 (D7), P0.02 (D19), P1.11 (D14)
//
// Special value for unused pins:
#define PIN_UNUSED                -1

#if (IMU_BUS == IMU_BUS_SPI)
  // --- SPI Configuration ---
  // Replace these with the pins reported by imu_finder:
  #define PIN_IMU_SCK             NRF_GPIO_PIN_MAP(0, 17) // PLACEHOLDER: Clock (SCL/SCK)
  #define PIN_IMU_MOSI            NRF_GPIO_PIN_MAP(0, 20) // PLACEHOLDER: Master Out Slave In (SDA/SDI)
  #define PIN_IMU_MISO            NRF_GPIO_PIN_MAP(0, 22) // PLACEHOLDER: Master In Slave Out (SDO)
  #define PIN_IMU_CS              NRF_GPIO_PIN_MAP(0, 24) // PLACEHOLDER: Chip Select (CS)
  #define SPI_BUS_SPEED_HZ        8000000                 // 8 MHz high-speed SPI with SPIM EasyDMA

#elif (IMU_BUS == IMU_BUS_I2C)
  // --- I2C Configuration ---
  // Replace these with the pins reported by imu_finder:
  #define PIN_IMU_SDA             NRF_GPIO_PIN_MAP(0, 20) // PLACEHOLDER: Serial Data
  #define PIN_IMU_SCL             NRF_GPIO_PIN_MAP(0, 17) // PLACEHOLDER: Serial Clock
  #define IMU_I2C_ADDR            0x6A                    // 0x6A or 0x6B (set by SDO pin voltage)
  #define I2C_BUS_SPEED_HZ        400000                  // 400 kHz Fast-Mode I2C
#endif

// Interrupt Pins (Data-Ready):
// If IMU_INT1 is connected, the firmware will sample via hardware interrupt.
// If set to PIN_UNUSED, the firmware falls back to high-resolution polling.
#define PIN_IMU_INT1              NRF_GPIO_PIN_MAP(1, 00) // PLACEHOLDER: INT1 Data-Ready
#define PIN_IMU_INT2              PIN_UNUSED              // PLACEHOLDER: INT2 (Optional)

// ==============================================================================
// 4. LSM6DSV SENSOR TUNING & ODR
// ==============================================================================
// NOTE ON ODR: The ST LSM6DSV native hardware Output Data Rate is 960 Hz in
// High-Performance mode (register CTRL2_G = 0x09, CTRL1_XL = 0x09).
// Reports are packaged and sent over USB HID at 1000 Hz (1 ms bInterval).
#define LSM6DSV_ODR_HZ            960     // Hardware sensor ODR
#define USB_POLL_RATE_HZ          1000    // USB HID reporting rate (1 ms bInterval)

// Full-Scale Ranges:
// Gyroscope: 0 = 125 dps, 1 = 250 dps, 2 = 500 dps, 3 = 1000 dps, 4 = 2000 dps, 5 = 4000 dps
#define LSM6DSV_GYRO_FS_DPS       2000    // ±2000 dps full-scale (standard for JoyShockMapper)
// Accelerometer: 0 = ±2g, 1 = ±4g, 2 = ±8g, 3 = ±16g
#define LSM6DSV_ACCEL_FS_G        4       // ±4g full-scale

// ==============================================================================
// 5. GYRO CALIBRATION & FILTERING
// ==============================================================================
// On boot, keep the device completely still for ~1.2 seconds.
// The firmware calculates zero-rate bias offset across CALIBRATION_SAMPLES.
#define CALIBRATION_SAMPLES       1000    // ~1.04 seconds @ 960 Hz
#define GYRO_STATIONARY_THRESH    120     // LSB threshold to ensure no movement during calibration
#define GYRO_DEADBAND_LSB         2       // Noise gate (suppress drift when resting)

// Gyro Axis Orientation Mapping (Invert/Swap axes to match physical mounting):
// Adjust these if pitch, roll, or yaw are reversed:
#define GYRO_AXIS_INVERT_X        false
#define GYRO_AXIS_INVERT_Y        false
#define GYRO_AXIS_INVERT_Z        false

// ==============================================================================
// 6. USB HID / JOYSHOCKMAPPER EMULATION
// ==============================================================================
// Emulates Sony DualShock 4 (VID 0x054C, PID 0x05C4) so JoyShockMapper immediately
// detects the device as a motion-capable controller with zero driver setup.
#define USB_VID                   0x054C
#define USB_PID                   0x05C4
#define USB_PRODUCT_NAME          "Smol Slime Gyro 1000Hz"
#define USB_MANUFACTURER_NAME     "InputLabs / SmolSlime"

#endif // CONFIG_H_
